import React, { useState, useEffect } from 'react';
import './App.css';
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
import extenso from 'extenso';
import { supabase } from './server';

pdfMake.vfs = (pdfFonts && pdfFonts.pdfMake) ? pdfFonts.pdfMake.vfs : pdfFonts.vfs;

export default function App() {
  // --- SISTEMA DE LOGIN ---
  const [autenticado, setAutenticado] = useState(() => localStorage.getItem('getvisa_auth') === 'true');
  const [senhaDigitada, setSenhaDigitada] = useState('');
  const [termoBusca, setTermoBusca] = useState('');
  const SENHA_SISTEMA = "getvisa2026";

  // --- LOGO GETVISA (SUBSTITUA PELA SUA) ---
  const LOGO_BASE64 = "data:image/png;base64,"; // Deixe vazio por enquanto, depois coloque sua logo

  const [telaAtiva, setTelaAtiva] = useState('gerador');
  const [faturaEditandoId, setFaturaEditandoId] = useState(null);
  const [carregando, setCarregando] = useState(false);

  // --- CAMPOS DA FATURA ---
  const [fatura, setFatura] = useState('');
  const [dataEmissao, setDataEmissao] = useState('');
  const [vencimento, setVencimento] = useState('');
  const [valor, setValor] = useState('');
  const [descritivo, setDescritivo] = useState('');
  const [listaFaturas, setListaFaturas] = useState([]);

  // --- CAMPOS DO CLIENTE PJ ---
  const [clientePjId, setClientePjId] = useState('');
  const [razaoSocial, setRazaoSocial] = useState('');
  const [nomeFantasia, setNomeFantasia] = useState('');
  const [cnpj, setCnpj] = useState('');
  const [emailCliente, setEmailCliente] = useState('');
  const [telefoneCliente, setTelefoneCliente] = useState('');
  const [enderecoCliente, setEnderecoCliente] = useState('');
  const [cep, setCep] = useState('');
  const [logradouro, setLogradouro] = useState('');
  const [numero, setNumero] = useState('');
  const [complemento, setComplemento] = useState('');
  const [cidade, setCidade] = useState('');
  const [estado, setEstado] = useState('');
  const [inscricaoEstadual, setInscricaoEstadual] = useState('Isento');
  const [inscricaoMunicipal, setInscricaoMunicipal] = useState('');

  // --- LISTA DE CLIENTES PJ PARA AUTOCOMPLETE ---
  const [listaClientes, setListaClientes] = useState([]);
  const [mostrarSugestoes, setMostrarSugestoes] = useState(false);

  // --- MÁSCARAS ---
  const handleCnpjChange = (e) => {
    let v = e.target.value.replace(/\D/g, "");
    v = v.replace(/^(\d{2})(\d)/, "$1.$2");
    v = v.replace(/^(\d{2})\.(\d{3})(\d)/, "$1.$2.$3");
    v = v.replace(/\.(\d{3})(\d)/, ".$1/$2");
    v = v.replace(/(\d{4})(\d)/, "$1-$2");
    setCnpj(v);
  };

  const handleCepChange = (e) => {
    let value = e.target.value.replace(/\D/g, '');
    if (value.length > 5) {
      value = value.replace(/^(\d{5})(\d)/, '$1-$2');
    }
    setCep(value);
  };

  // --- FUNÇÕES ---
  const fazerLogin = () => {
    if (senhaDigitada === SENHA_SISTEMA) {
      setAutenticado(true);
      localStorage.setItem('getvisa_auth', 'true');
    } else {
      alert('❌ Senha incorreta!');
    }
  };

  const fazerLogout = () => {
    setAutenticado(false);
    setSenhaDigitada('');
    localStorage.removeItem('getvisa_auth');
  };

  const formatarData = (dataString) => {
    if (!dataString) return '';
    const [ano, mes, dia] = dataString.split('-');
    return `${dia}/${mes}/${ano}`;
  };

  const verificarStatus = (fat) => {
    if (fat.status === 'Cancelado') return 'Cancelado';
    if (fat.status === 'Pago') return 'Pago';
    if (fat.status === 'Vencido') return 'Vencido';
    const hoje = new Date();
    hoje.setHours(0, 0, 0, 0);
    if (fat.vencimento) {
      const [ano, mes, dia] = fat.vencimento.split('-');
      const dataVenc = new Date(ano, mes - 1, dia);
      if (dataVenc < hoje) return 'Vencido';
    }
    return 'Pendente';
  };

  const calcularDiasVencimento = (dataVencimento) => {
    if (!dataVencimento) return 999;
    const hoje = new Date();
    hoje.setHours(0, 0, 0, 0);
    const [ano, mes, dia] = dataVencimento.split('-');
    const dataVenc = new Date(ano, mes - 1, dia);
    const diffTime = dataVenc - hoje;
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  // --- BUSCAR PRÓXIMO NÚMERO DE FATURA ---
  const gerarProximoNumeroFatura = async () => {
    try {
      const { data, error } = await supabase
        .from('faturas')
        .select('fatura')
        .order('fatura', { ascending: false })
        .limit(1);

      if (error) throw error;

      let maxNum = 0;
      if (data && data.length > 0) {
        const numStr = String(data[0].fatura).replace(/\D/g, '');
        const num = parseInt(numStr, 10);
        if (!isNaN(num) && num > maxNum) {
          maxNum = num;
        }
      }
      const proximoNum = maxNum + 1;
      setFatura(String(proximoNum).padStart(3, '0'));
    } catch (erro) {
      console.error("Erro ao buscar próximo número:", erro);
    }
  };

  // --- BUSCAR CLIENTES PJ (autocomplete) ---
  const buscarClientes = async (termo) => {
    if (!termo || termo.length < 2) {
      setListaClientes([]);
      setMostrarSugestoes(false);
      return;
    }

    try {
      const { data, error } = await supabase
        .from('clientes_pj')
        .select('*')
        .or(`razao_social.ilike.%${termo}%,nome_fantasia.ilike.%${termo}%,cnpj.ilike.%${termo}%,email.ilike.%${termo}%`)
        .limit(10);

      if (error) throw error;
      setListaClientes(data || []);
      setMostrarSugestoes(data && data.length > 0);
    } catch (erro) {
      console.error("Erro ao buscar clientes:", erro);
    }
  };

  // --- SELECIONAR CLIENTE PJ ---
  const selecionarCliente = (cliente) => {
    setClientePjId(cliente.id);
    setRazaoSocial(cliente.razao_social || '');
    setNomeFantasia(cliente.nome_fantasia || '');
    setCnpj(cliente.cnpj || '');
    setEmailCliente(cliente.email || '');
    setTelefoneCliente(cliente.telefone || '');
    setEnderecoCliente(cliente.endereco || '');
    setCep(cliente.cep || '');
    setLogradouro(cliente.logradouro || '');
    setNumero(cliente.numero || '');
    setComplemento(cliente.complemento || '');
    setCidade(cliente.cidade || '');
    setEstado(cliente.estado || '');
    setInscricaoEstadual(cliente.inscricao_estadual || 'Isento');
    setInscricaoMunicipal(cliente.inscricao_municipal || '');
    setMostrarSugestoes(false);
    setListaClientes([]);
  };

  // --- SALVAR CLIENTE PJ ---
  const salvarCliente = async () => {
    if (!razaoSocial || !cnpj) return alert("Preencha Razão Social e CNPJ.");

    const dadosCliente = {
      razao_social: razaoSocial,
      nome_fantasia: nomeFantasia,
      cnpj,
      inscricao_estadual: inscricaoEstadual,
      inscricao_municipal: inscricaoMunicipal,
      email: emailCliente,
      telefone: telefoneCliente,
      endereco: enderecoCliente,
      cep,
      logradouro,
      numero,
      complemento,
      cidade,
      estado
    };

    try {
      const { data: existing, error: searchError } = await supabase
        .from('clientes_pj')
        .select('id')
        .eq('cnpj', cnpj)
        .maybeSingle();

      if (searchError && searchError.code !== 'PGRST116') throw searchError;

      if (existing) {
        const { error: updateError } = await supabase
          .from('clientes_pj')
          .update(dadosCliente)
          .eq('cnpj', cnpj);

        if (updateError) throw updateError;
        alert("✅ Cadastro do cliente ATUALIZADO com sucesso!");
      } else {
        const { error: insertError } = await supabase
          .from('clientes_pj')
          .insert([dadosCliente]);

        if (insertError) throw insertError;
        alert("✅ Novo cliente salvo no banco!");
      }
    } catch (erro) {
      console.error("Erro ao salvar cliente:", erro);
      alert("Erro ao salvar cliente.");
    }
  };

  // --- BUSCAR FATURAS ---
  const buscarFaturas = async () => {
    setCarregando(true);
    try {
      const { data, error } = await supabase
        .from('faturas')
        .select('*')
        .order('data_registro', { ascending: false });

      if (error) throw error;
      setListaFaturas(data || []);
    } catch (erro) {
      console.error("Erro ao buscar faturas:", erro);
    } finally {
      setCarregando(false);
    }
  };

  // --- EFFECTS ---
  useEffect(() => {
    if (autenticado && !faturaEditandoId && telaAtiva === 'gerador') {
      const hoje = new Date();
      const ano = hoje.getFullYear();
      const mes = String(hoje.getMonth() + 1).padStart(2, '0');
      const dia = String(hoje.getDate()).padStart(2, '0');
      setDataEmissao(`${ano}-${mes}-${dia}`);

      const dataVenc = new Date(hoje);
      dataVenc.setDate(dataVenc.getDate() + 7);
      setVencimento(`${dataVenc.getFullYear()}-${String(dataVenc.getMonth() + 1).padStart(2, '0')}-${String(dataVenc.getDate()).padStart(2, '0')}`);

      gerarProximoNumeroFatura();
    }
  }, [faturaEditandoId, telaAtiva, autenticado]);

  useEffect(() => {
    if (autenticado && telaAtiva === 'dashboard') buscarFaturas();
  }, [telaAtiva, autenticado]);

  // --- HANDLERS ---
  const handleDataEmissaoChange = (e) => {
    const novaData = e.target.value;
    setDataEmissao(novaData);
    if (novaData) {
      const [ano, mes, dia] = novaData.split('-');
      const dataObj = new Date(ano, mes - 1, dia);
      dataObj.setDate(dataObj.getDate() + 7);
      setVencimento(`${dataObj.getFullYear()}-${String(dataObj.getMonth() + 1).padStart(2, '0')}-${String(dataObj.getDate()).padStart(2, '0')}`);
    }
  };

  const handleValorChange = (e) => {
    let value = e.target.value.replace(/\D/g, '');
    value = (value / 100).toFixed(2) + '';
    value = value.replace(".", ",");
    value = value.replace(/(\d)(?=(\d{3})+(?!\d))/g, "$1.");
    setValor(value);
  };

  const handleClienteBusca = (e) => {
    const valor = e.target.value;
    setRazaoSocial(valor);
    buscarClientes(valor);
  };

  // --- ALTERAR STATUS ---
  const alterarStatusFatura = async (idFatura, novoStatus) => {
    if (novoStatus === 'Cancelado' && !window.confirm("Tem certeza que deseja CANCELAR esta fatura?")) return;
    try {
      const { error } = await supabase
        .from('faturas')
        .update({ status: novoStatus })
        .eq('id', idFatura);

      if (error) throw error;
      alert(`✅ Fatura marcada como ${novoStatus}!`);
      buscarFaturas();
    } catch (erro) {
      console.error("Erro ao atualizar status:", erro);
      alert("Erro ao atualizar status.");
    }
  };

  // --- CARREGAR PARA EDIÇÃO ---
  const carregarParaEdicao = (fat) => {
    setFaturaEditandoId(fat.id);
    setFatura(fat.fatura || '');
    setDataEmissao(fat.emissao || '');
    setVencimento(fat.vencimento || '');
    setValor(fat.valor || '');
    setRazaoSocial(fat.cliente_razao_social || '');
    setNomeFantasia(fat.cliente_nome_fantasia || '');
    setCnpj(fat.cliente_cnpj || '');
    setEmailCliente(fat.cliente_email || '');
    setTelefoneCliente(fat.cliente_telefone || '');
    setEnderecoCliente(fat.cliente_endereco || '');
    setClientePjId(fat.cliente_pj_id || '');
    setDescritivo(fat.descritivo || '');
    setTelaAtiva('gerador');
  };

  const cancelarEdicao = () => {
    setFaturaEditandoId(null);
    setValor('');
    setDescritivo('');
    setRazaoSocial('');
    setNomeFantasia('');
    setCnpj('');
    setEmailCliente('');
    setTelefoneCliente('');
    setEnderecoCliente('');
    setClientePjId('');
    gerarProximoNumeroFatura();
  };

  // --- PDF ---
  const montarLayoutPDF = (dados) => {
  let valorExtenso = "";
  try {
    // CORREÇÃO: Limpar valor corretamente
    const valorLimpo = String(dados.valor)
      .replace(/\./g, '')   // Remove pontos de milhar
      .replace(',', '.');    // Troca vírgula por ponto
    
    const valorNumero = parseFloat(valorLimpo);
    if (!isNaN(valorNumero) && valorNumero > 0) {
      valorExtenso = extenso(valorNumero, { mode: 'currency' }).toUpperCase();
    } else {
      valorExtenso = "VALOR INVÁLIDO";
    }
  } catch (e) { 
    valorExtenso = "VALOR INVÁLIDO"; 
  }

  // Formatar valor para exibição
  const valorFormatado = dados.valor || '0,00';

  const colunasCabecalho = [];

  if (LOGO_BASE64 && LOGO_BASE64.length > 100) {
    colunasCabecalho.push({
      image: LOGO_BASE64,
      width: 80,
      alignment: 'left'
    });
  }

  colunasCabecalho.push({
    stack: [
      { text: 'GETVISA TURISMO LTDA', fontSize: 16, bold: true, color: '#1a237e', margin: [0, 0, 0, 3] },
      { text: 'Av. Francisco da Cruz Nunes, 5428 - Loja 115', fontSize: 10, color: '#555', margin: [0, 0, 0, 2] },
      { text: 'Niterói - RJ - CEP 24350-310', fontSize: 10, color: '#555', margin: [0, 0, 0, 2] },
      { text: 'CNPJ: 38.202.532/0001-84', fontSize: 10, color: '#555', margin: [0, 0, 0, 2] },
      { text: 'TELEFONE: (21) 2608-3931', fontSize: 10, color: '#555',}
    ],
    alignment: (LOGO_BASE64 && LOGO_BASE64.length > 100) ? 'right' : 'center',
    margin: [0, 10, 0, 0]
  });

  return {
    content: [
      {
        table: {
          widths: ['*'],
          body: [
            [
              {
                margin: [20, 20, 20, 20],
                stack: [
                  // CABEÇALHO
                  { columns: colunasCabecalho, margin: [0, 0, 0, 20] },
                  
                  // TÍTULO
                  { 
                    text: 'FATURA DE PRESTAÇÃO DE SERVIÇO', 
                    fontSize: 18, 
                    bold: true, 
                    alignment: 'center', 
                    color: '#1a237e',
                    margin: [0, 0, 0, 15] 
                  },
                  
                  // LINHA DIVISÓRIA
                  { 
                    canvas: [{ type: 'line', x1: 0, y1: 0, x2: 515, y2: 0, lineWidth: 2, color: '#1a237e' }],
                    margin: [0, 0, 0, 15]
                  },
                  
                  // TABELA DE DADOS DA FATURA
                  {
                    table: {
                      widths: ['25%', '25%', '25%', '25%'],
                      body: [
                        [
                          { text: 'DATA EMISSÃO', bold: true, fontSize: 9, color: '#666', alignment: 'center', fillColor: '#f5f5f5' },
                          { text: 'VENCIMENTO', bold: true, fontSize: 9, color: '#666', alignment: 'center', fillColor: '#f5f5f5' },
                          { text: 'NUM. FATURA', bold: true, fontSize: 9, color: '#666', alignment: 'center', fillColor: '#f5f5f5' },
                          { text: 'VALOR (R$)', bold: true, fontSize: 9, color: '#666', alignment: 'center', fillColor: '#f5f5f5' }
                        ],
                        [
                          { text: formatarData(dados.emissao), fontSize: 11, alignment: 'center', margin: [0, 5, 0, 5] },
                          { text: formatarData(dados.vencimento), fontSize: 11, alignment: 'center', margin: [0, 5, 0, 5] },
                          { text: dados.fatura, fontSize: 11, alignment: 'center', margin: [0, 5, 0, 5] },
                          { text: `R$ ${valorFormatado}`, fontSize: 11, alignment: 'center', margin: [0, 5, 0, 5], bold: true, color: '#1a237e' }
                        ]
                      ]
                    },
                    layout: {
                      hLineWidth: (i) => i === 0 || i === 1 ? 1 : 0.5,
                      vLineWidth: () => 0.5,
                      hLineColor: (i) => i === 0 || i === 1 ? '#1a237e' : '#ccc',
                      vLineColor: () => '#ccc',
                      paddingLeft: () => 8,
                      paddingRight: () => 8,
                      paddingTop: () => 5,
                      paddingBottom: () => 5
                    },
                    margin: [0, 0, 0, 20]
                  },
                  
                  // DADOS DO CLIENTE
                  {
                    table: {
                      widths: ['*'],
                      body: [
                        [
                          {
                            stack: [
                              { text: 'DADOS DO CLIENTE', bold: true, fontSize: 11, color: '#1a237e', margin: [0, 0, 0, 8] },
                              { text: [{ text: 'RAZÃO SOCIAL: ', bold: true }, dados.cliente_razao_social || ''], fontSize: 10, margin: [0, 0, 0, 3] },
                              { text: [{ text: 'NOME FANTASIA: ', bold: true }, dados.cliente_nome_fantasia || ''], fontSize: 10, margin: [0, 0, 0, 3] },
                              { text: [{ text: 'CNPJ: ', bold: true }, dados.cliente_cnpj || ''], fontSize: 10, margin: [0, 0, 0, 3] },
                              { text: [{ text: 'ENDEREÇO: ', bold: true }, dados.cliente_endereco || ''], fontSize: 10, margin: [0, 0, 0, 3] },
                              { text: [{ text: 'TELEFONE: ', bold: true }, dados.cliente_telefone || ''], fontSize: 10 }
                            ],
                            margin: [10, 10, 10, 10]
                          }
                        ]
                      ]
                    },
                    layout: {
                      hLineWidth: () => 0.5,
                      vLineWidth: () => 0.5,
                      hLineColor: () => '#ccc',
                      vLineColor: () => '#ccc',
                      paddingLeft: () => 5,
                      paddingRight: () => 5,
                      paddingTop: () => 5,
                      paddingBottom: () => 5
                    },
                    margin: [0, 0, 0, 15]
                  },
                  
                  // DESCRITIVO
                  {
                    table: {
                      widths: ['*'],
                      body: [
                        [
                          {
                            stack: [
                              { text: 'DESCRITIVO DO SERVIÇO', bold: true, fontSize: 11, color: '#1a237e', margin: [0, 0, 0, 8] },
                              { text: dados.descritivo || '', fontSize: 10 }
                            ],
                            margin: [10, 10, 10, 10]
                          }
                        ]
                      ]
                    },
                    layout: {
                      hLineWidth: () => 0.5,
                      vLineWidth: () => 0.5,
                      hLineColor: () => '#ccc',
                      vLineColor: () => '#ccc',
                      paddingLeft: () => 5,
                      paddingRight: () => 5,
                      paddingTop: () => 5,
                      paddingBottom: () => 5
                    },
                    margin: [0, 0, 0, 15]
                  },
                  
                  // VALOR POR EXTENSO
                  {
                    table: {
                      widths: ['*'],
                      body: [
                        [
                          {
                            stack: [
                              { text: 'VALOR POR EXTENSO', bold: true, fontSize: 11, color: '#1a237e', margin: [0, 0, 0, 8] },
                              { text: valorExtenso, fontSize: 11, color: '#333' }
                            ],
                            margin: [10, 10, 10, 10]
                          }
                        ]
                      ]
                    },
                    layout: {
                      hLineWidth: () => 0.5,
                      vLineWidth: () => 0.5,
                      hLineColor: () => '#ccc',
                      vLineColor: () => '#ccc',
                      paddingLeft: () => 5,
                      paddingRight: () => 5,
                      paddingTop: () => 5,
                      paddingBottom: () => 5
                    },
                    margin: [0, 0, 0, 15]
                  },
                  
                  // DADOS BANCÁRIOS
                  {
                    table: {
                      widths: ['*'],
                      body: [
                        [
                          {
                            stack: [
                              { text: 'DADOS PARA PAGAMENTO', bold: true, fontSize: 11, color: '#1a237e', margin: [0, 0, 0, 8] },
                              { 
                                columns: [
                                  { 
                                    stack: [
                                      { text: [{ text: 'PIX: ', bold: true }, 'financeiromilleviagens@getvisa.com.br'], fontSize: 10, margin: [0, 0, 0, 3] },
                                      { text: [{ text: 'BANCO: ', bold: true }, 'CAIXA ECONÔMICA'], fontSize: 10, margin: [0, 0, 0, 3] },
                                      { text: [{ text: 'AGÊNCIA: ', bold: true }, '0174'], fontSize: 10 }
                                    ],
                                    width: '50%'
                                  },
                                  { 
                                    stack: [
                                      { text: [{ text: 'CONTA CORRENTE: ', bold: true }, '579345449-3'], fontSize: 10, margin: [0, 0, 0, 3] },
                                      { text: [{ text: 'FAVORECIDO: ', bold: true }, 'GETVISA TURISMO LTDA'], fontSize: 10, margin: [0, 0, 0, 3] },
                                      { text: [{ text: 'CNPJ: ', bold: true }, '38.202.532/0001-84'], fontSize: 10 }
                                    ],
                                    width: '50%'
                                  }
                                ]
                              }
                            ],
                            margin: [10, 10, 10, 10]
                          }
                        ]
                      ]
                    },
                    layout: {
                      hLineWidth: () => 0.5,
                      vLineWidth: () => 0.5,
                      hLineColor: () => '#ccc',
                      vLineColor: () => '#ccc',
                      paddingLeft: () => 5,
                      paddingRight: () => 5,
                      paddingTop: () => 5,
                      paddingBottom: () => 5
                    },
                    margin: [0, 0, 0, 15]
                  },
                  
                  // RODAPÉ
                  { 
                    text: 'Documento gerado eletronicamente - Getvisa Turismo Ltda', 
                    fontSize: 8, 
                    color: '#999', 
                    alignment: 'center',
                    margin: [0, 10, 0, 0]
                  }
                ]
              }
            ]
          ]
        },
        layout: {
          hLineWidth: () => 1,
          vLineWidth: () => 1,
          hLineColor: () => '#1a237e',
          vLineColor: () => '#1a237e',
          paddingLeft: () => 0,
          paddingRight: () => 0,
          paddingTop: () => 0,
          paddingBottom: () => 0
        }
      }
    ],
    defaultStyle: { fontSize: 10 },
    pageMargins: [40, 40, 40, 40]
  };
};

  const gerarArquivoPDF = (dados) => {
    const docDefinition = montarLayoutPDF(dados);
    pdfMake.createPdf(docDefinition).download(`Fatura_${dados.fatura}.pdf`);
  };

  // --- PREPARAR EMAIL ---
  const prepararEmailOficial = (fat) => {
    if (!fat.cliente_email) {
      alert("⚠️ Esta fatura não tem um e-mail cadastrado.");
      return;
    }
    gerarArquivoPDF(fat);
    const assunto = encodeURIComponent(`Fatura ${fat.fatura} - Getvisa Turismo`);
    const corpo = encodeURIComponent(`Prezados ${fat.cliente_razao_social},\n\nSegue em anexo a fatura nº ${fat.fatura} referente aos serviços prestados.\n\nValor: R$ ${fat.valor}\nVencimento: ${formatarData(fat.vencimento)}\n\nNossa chave PIX para pagamento é: getvisa@getvisa.com.br\n\nQualquer dúvida, estamos à disposição!\n\nAtenciosamente,\nGetvisa Turismo Ltda`);
    window.location.href = `mailto:${fat.cliente_email}?subject=${assunto}&body=${corpo}`;
  };

  // --- SALVAR FATURA ---
  const salvarEGerarFatura = async () => {
    if (!fatura || !valor || !razaoSocial) return alert("Preencha Fatura, Valor e Razão Social.");

    const enderecoCompleto = `${logradouro}, ${numero} ${complemento ? '- ' + complemento : ''} - ${cidade}/${estado} - CEP: ${cep}`;

    const dadosFatura = {
      fatura,
      cliente_pj_id: clientePjId || null,
      cliente_razao_social: razaoSocial,
      cliente_nome_fantasia: nomeFantasia,
      cliente_cnpj: cnpj,
      cliente_email: emailCliente,
      cliente_telefone: telefoneCliente,
      cliente_endereco: enderecoCompleto || enderecoCliente,
      valor,
      emissao: dataEmissao,
      vencimento,
      descritivo,
      status: faturaEditandoId ? undefined : "Pendente",
      data_registro: faturaEditandoId ? undefined : new Date().toISOString()
    };

    try {
      if (faturaEditandoId) {
        const { error } = await supabase
          .from('faturas')
          .update(dadosFatura)
          .eq('id', faturaEditandoId);

        if (error) throw error;
        alert("✅ Fatura ATUALIZADA e PDF gerado!");
        setFaturaEditandoId(null);
      } else {
        const { error } = await supabase
          .from('faturas')
          .insert([dadosFatura]);

        if (error) throw error;
        alert("✅ Nova Fatura SALVA e PDF gerado!");
      }

      gerarArquivoPDF(dadosFatura);

      setValor('');
      setDescritivo('');
      setRazaoSocial('');
      setNomeFantasia('');
      setCnpj('');
      setEmailCliente('');
      setTelefoneCliente('');
      setEnderecoCliente('');
      setClientePjId('');
      gerarProximoNumeroFatura();

      if (telaAtiva === 'dashboard') buscarFaturas();

    } catch (erro) {
      console.error("Erro:", erro);
      alert("Erro ao processar fatura.");
    }
  };

  // --- ALERTAS ---
  const faturasAlerta = listaFaturas.filter(fat => {
    if (verificarStatus(fat) !== 'Pendente') return false;
    const dias = calcularDiasVencimento(fat.vencimento);
    return dias >= 0 && dias <= 2;
  });

  // --- TELA DE LOGIN ---
  if (!autenticado) {
    return (
      <div style={{ display: 'flex', height: '100vh', justifyContent: 'center', alignItems: 'center', backgroundColor: '#f4f4f9', fontFamily: 'Arial, sans-serif' }}>
        <div style={{ padding: '40px', backgroundColor: 'white', borderRadius: '8px', boxShadow: '0 4px 12px rgba(0,0,0,0.1)', textAlign: 'center', width: '100%', maxWidth: '350px' }}>
          <h2 style={{ color: '#333', marginBottom: '10px' }}>🔒 Acesso Restrito</h2>
          <p style={{ color: '#666', marginBottom: '20px', fontSize: '14px' }}>Sistema de Faturas - Getvisa Turismo</p>
          <input
            type="password"
            value={senhaDigitada}
            onChange={(e) => setSenhaDigitada(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && fazerLogin()}
            style={{ padding: '12px', width: '100%', marginBottom: '15px', border: '1px solid #ccc', borderRadius: '4px', boxSizing: 'border-box', fontSize: '16px' }}
            placeholder="Digite a senha..."
          />
          <button
            onClick={fazerLogin}
            style={{ padding: '12px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer', width: '100%', fontWeight: 'bold', fontSize: '16px' }}
          >
            Entrar
          </button>
        </div>
      </div>
    );
  }

  // --- TELA PRINCIPAL ---
  return (
    <div style={{ padding: '30px', maxWidth: '1100px', margin: '0 auto', fontFamily: 'Arial, sans-serif' }}>

      <div style={{ textAlign: 'center', marginBottom: '25px' }}>
        <h1 style={{ color: '#333', margin: 0 }}>Sistema de Faturas - Getvisa Turismo</h1>
      </div>

      <div style={{ display: 'flex', gap: '15px', marginBottom: '30px', justifyContent: 'center', alignItems: 'center', flexWrap: 'wrap' }}>
        <button onClick={() => { setTelaAtiva('gerador'); cancelarEdicao(); }} style={telaAtiva === 'gerador' ? styles.btnMenuAtivo : styles.btnMenuInativo}>
          📝 {faturaEditandoId ? 'Editando Fatura...' : 'Gerar Nova Fatura'}
        </button>
        <button onClick={() => setTelaAtiva('dashboard')} style={telaAtiva === 'dashboard' ? styles.btnMenuAtivo : styles.btnMenuInativo}>
          📊 Painel de Faturas
        </button>
        <button onClick={fazerLogout} style={{ backgroundColor: '#dc3545', color: 'white', border: 'none', padding: '12px 24px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '15px' }}>
          Sair 🚪
        </button>
      </div>

      {telaAtiva === 'gerador' && (
        <div>
          {faturaEditandoId && (
            <div style={{ backgroundColor: '#fff3cd', padding: '10px', borderRadius: '5px', marginBottom: '15px', textAlign: 'center', color: '#856404', fontWeight: 'bold' }}>
              ⚠️ Você está editando a fatura #{fatura}.
            </div>
          )}

          <fieldset style={styles.fieldset}>
            <legend style={styles.legend}>Dados da Fatura</legend>
            <div style={styles.row}>
              <div style={styles.inputGroup}><label style={styles.label}>Nº Fatura:</label><input type="text" style={styles.input} value={fatura} onChange={e => setFatura(e.target.value)} /></div>
              <div style={styles.inputGroup}><label style={styles.label}>Emissão:</label><input type="date" style={styles.input} value={dataEmissao} onChange={handleDataEmissaoChange} /></div>
              <div style={styles.inputGroup}><label style={styles.label}>Vencimento:</label><input type="date" style={styles.input} value={vencimento} onChange={e => setVencimento(e.target.value)} /></div>
              <div style={styles.inputGroup}><label style={styles.label}>Valor (R$):</label><input type="text" style={styles.input} value={valor} onChange={handleValorChange} placeholder="0,00" /></div>
            </div>
          </fieldset>

          <fieldset style={styles.fieldset}>
            <legend style={styles.legend}>Dados do Cliente (Pessoa Jurídica)</legend>
            
            <div style={{ ...styles.row, position: 'relative' }}>
              <div style={{ ...styles.inputGroup, flex: 2 }}>
                <label style={styles.label}>Razão Social:</label>
                <input
                  type="text"
                  style={styles.input}
                  value={razaoSocial}
                  onChange={handleClienteBusca}
                  placeholder="Digite a razão social..."
                  autoComplete="off"
                />
                {mostrarSugestoes && listaClientes.length > 0 && (
                  <div style={{
                    position: 'absolute',
                    top: '100%',
                    left: 0,
                    right: 0,
                    backgroundColor: 'white',
                    border: '1px solid #ccc',
                    borderRadius: '4px',
                    maxHeight: '200px',
                    overflowY: 'auto',
                    zIndex: 1000,
                    marginTop: '2px',
                    boxShadow: '0 4px 8px rgba(0,0,0,0.1)'
                  }}>
                    {listaClientes.map(cli => (
                      <div
                        key={cli.id}
                        onClick={() => selecionarCliente(cli)}
                        style={{
                          padding: '10px',
                          cursor: 'pointer',
                          borderBottom: '1px solid #eee'
                        }}
                        onMouseEnter={(e) => e.target.style.backgroundColor = '#f0f0f0'}
                        onMouseLeave={(e) => e.target.style.backgroundColor = 'white'}
                      >
                        <div style={{ fontWeight: 'bold' }}>{cli.razao_social}</div>
                        <div style={{ fontSize: '12px', color: '#666' }}>
                          CNPJ: {cli.cnpj} | {cli.nome_fantasia || 'Sem fantasia'}
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
              <div style={{ ...styles.inputGroup, flex: 1 }}>
                <label style={styles.label}>CNPJ:</label>
                <input type="text" style={styles.input} value={cnpj} onChange={handleCnpjChange} maxLength="18" placeholder="00.000.000/0000-00" />
              </div>
            </div>

            <div style={styles.row}>
              <div style={{ ...styles.inputGroup, flex: 1 }}>
                <label style={styles.label}>Nome Fantasia:</label>
                <input type="text" style={styles.input} value={nomeFantasia} onChange={e => setNomeFantasia(e.target.value.toUpperCase())} />
              </div>
              <div style={{ ...styles.inputGroup, flex: 1 }}>
                <label style={styles.label}>Inscrição Estadual:</label>
                <input type="text" style={styles.input} value={inscricaoEstadual} onChange={e => setInscricaoEstadual(e.target.value.toUpperCase())} />
              </div>
              <div style={{ ...styles.inputGroup, flex: 1 }}>
                <label style={styles.label}>Inscrição Municipal:</label>
                <input type="text" style={styles.input} value={inscricaoMunicipal} onChange={e => setInscricaoMunicipal(e.target.value.toUpperCase())} />
              </div>
            </div>

            <div style={styles.row}>
              <div style={{ ...styles.inputGroup, flex: 1 }}>
                <label style={styles.label}>E-mail:</label>
                <input type="email" style={styles.input} value={emailCliente} onChange={e => setEmailCliente(e.target.value.toLowerCase())} placeholder="contato@empresa.com" />
              </div>
              <div style={{ ...styles.inputGroup, flex: 1 }}>
                <label style={styles.label}>Telefone:</label>
                <input type="text" style={styles.input} value={telefoneCliente} onChange={e => setTelefoneCliente(e.target.value)} placeholder="(00) 0000-0000" />
              </div>
            </div>

            <div style={styles.row}>
              <div style={{ ...styles.inputGroup, flex: 1 }}>
                <label style={styles.label}>CEP:</label>
                <input type="text" style={styles.input} value={cep} onChange={handleCepChange} maxLength="9" placeholder="00000-000" />
              </div>
              <div style={{ ...styles.inputGroup, flex: 2 }}>
                <label style={styles.label}>Logradouro:</label>
                <input type="text" style={styles.input} value={logradouro} onChange={e => setLogradouro(e.target.value.toUpperCase())} />
              </div>
              <div style={{ ...styles.inputGroup, flex: 1 }}>
                <label style={styles.label}>Número:</label>
                <input type="text" style={styles.input} value={numero} onChange={e => setNumero(e.target.value)} />
              </div>
            </div>
            <div style={styles.row}>
              <div style={{ ...styles.inputGroup, flex: 2 }}>
                <label style={styles.label}>Complemento:</label>
                <input type="text" style={styles.input} value={complemento} onChange={e => setComplemento(e.target.value.toUpperCase())} />
              </div>
              <div style={{ ...styles.inputGroup, flex: 2 }}>
                <label style={styles.label}>Cidade:</label>
                <input type="text" style={styles.input} value={cidade} onChange={e => setCidade(e.target.value.toUpperCase())} />
              </div>
              <div style={{ ...styles.inputGroup, flex: 1 }}>
                <label style={styles.label}>UF:</label>
                <input type="text" style={styles.input} value={estado} onChange={e => setEstado(e.target.value.toUpperCase())} maxLength="2" />
              </div>
            </div>

            <button onClick={salvarCliente} style={styles.btnGreenOutline}>
              💾 Salvar Cliente no Banco
            </button>
          </fieldset>

          <fieldset style={styles.fieldset}>
            <legend style={styles.legend}>Descritivo do Serviço</legend>
            <textarea 
              style={{ ...styles.input, height: '80px', resize: 'vertical' }} 
              value={descritivo} 
              onChange={e => setDescritivo(e.target.value.toUpperCase())} 
              placeholder="Ex: Assessoria para visto americano - Taxa consular + agendamento"
            />
          </fieldset>

          <div style={{ display: 'flex', gap: '10px' }}>
            <button onClick={salvarEGerarFatura} style={{ ...styles.btnGreenSolid, flex: 2 }}>
              {faturaEditandoId ? '💾 Atualizar Fatura e Gerar PDF' : '📄 Gerar PDF e Salvar Fatura'}
            </button>
            {faturaEditandoId && (
              <button onClick={cancelarEdicao} style={{ ...styles.btnGreenSolid, flex: 1, backgroundColor: '#6c757d' }}>
                ❌ Cancelar Edição
              </button>
            )}
          </div>
        </div>
      )}

      {telaAtiva === 'dashboard' && (
        <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '8px', border: '1px solid #ccc' }}>

          {faturasAlerta.length > 0 && (
            <div style={{ backgroundColor: '#fff3cd', borderLeft: '5px solid #ffc107', padding: '15px', marginBottom: '20px', borderRadius: '4px' }}>
              <h3 style={{ color: '#856404', marginTop: 0, marginBottom: '10px' }}>⚠️ Faturas vencendo em breve!</h3>
              <ul style={{ margin: 0, paddingLeft: '20px', color: '#856404' }}>
                {faturasAlerta.map(fat => {
                  const dias = calcularDiasVencimento(fat.vencimento);
                  let textoDias = dias === 0 ? 'VENCE HOJE!' : dias === 1 ? 'Vence amanhã' : 'Vence em 2 dias';
                  return (
                    <li key={fat.id} style={{ marginBottom: '5px' }}>
                      <strong>Fatura #{fat.fatura}</strong> - {fat.cliente_razao_social} (R$ {fat.valor})
                      <span style={{ marginLeft: '10px', backgroundColor: dias === 0 ? '#dc3545' : '#ffc107', color: dias === 0 ? 'white' : '#333', padding: '2px 6px', borderRadius: '4px', fontSize: '12px', fontWeight: 'bold' }}>
                        {textoDias}
                      </span>
                    </li>
                  );
                })}
              </ul>
            </div>
          )}

          <div style={{ marginBottom: '20px', backgroundColor: '#f8f9fa', padding: '15px', borderRadius: '8px', border: '1px solid #ddd' }}>
            <label style={{ fontWeight: 'bold', color: '#555', display: 'block', marginBottom: '8px' }}>Pesquisar Fatura:</label>
            <input 
              type="text" 
              placeholder="🔍 Digite o Nome do Cliente, CNPJ ou Número da Fatura..." 
              value={termoBusca}
              onChange={(e) => setTermoBusca(e.target.value.toUpperCase())}
              style={{ width: '100%', padding: '12px', borderRadius: '6px', border: '1px solid #ccc', fontSize: '16px', boxSizing: 'border-box' }}
            />
          </div>

          {carregando ? (
            <p style={{ textAlign: 'center', color: '#666' }}>Carregando faturas...</p>
          ) : listaFaturas.length === 0 ? (
            <p style={{ color: '#666', marginTop: '20px' }}>Nenhuma fatura encontrada.</p>
          ) : (
            <div style={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '20px', minWidth: '800px' }}>
                <thead>
                  <tr style={{ backgroundColor: '#f8f9fa', borderBottom: '2px solid #ddd' }}>
                    <th style={styles.th}>Fatura</th>
                    <th style={styles.th}>Cliente</th>
                    <th style={styles.th}>Vencimento</th>
                    <th style={styles.th}>Valor</th>
                    <th style={styles.th}>Status</th>
                    <th style={styles.th}>Ações</th>
                  </tr>
                </thead>
                <tbody>
                  {listaFaturas
                    .filter(fat => {
                      if (!termoBusca) return true;
                      const busca = termoBusca.toLowerCase();
                      const numFat = String(fat.fatura || '').toLowerCase();
                      const razao = String(fat.cliente_razao_social || '').toLowerCase();
                      const cnpjFat = String(fat.cliente_cnpj || '').toLowerCase();
                      return numFat.includes(busca) || razao.includes(busca) || cnpjFat.includes(busca);
                    })
                    .map((fat) => {
                    const statusAtual = verificarStatus(fat);
                    return (
                      <tr key={fat.id} style={{ borderBottom: '1px solid #eee', opacity: statusAtual === 'Cancelado' ? 0.6 : 1 }}>
                        <td style={styles.td}><strong>#{fat.fatura}</strong></td>
                        <td style={styles.td}>
                          <div><strong>{fat.cliente_razao_social}</strong></div>
                          <div style={{ fontSize: '11px', color: '#666' }}>{fat.cliente_cnpj}</div>
                        </td>
                        <td style={styles.td}>{formatarData(fat.vencimento)}</td>
                        <td style={styles.td}><strong>R$ {fat.valor}</strong></td>
                        <td style={styles.td}>
                          <span style={{
                            padding: '5px 10px', borderRadius: '12px', fontSize: '12px', fontWeight: 'bold',
                            backgroundColor: statusAtual === 'Pago' ? '#d4edda' : statusAtual === 'Atrasado' ? '#f8d7da' : statusAtual === 'Cancelado' ? '#e2e3e5' : '#fff3cd',
                            color: statusAtual === 'Pago' ? '#155724' : statusAtual === 'Atrasado' ? '#721c24' : statusAtual === 'Cancelado' ? '#383d41' : '#856404'
                          }}>
                            {statusAtual}
                          </span>
                        </td>
                        <td style={{ ...styles.td, display: 'flex', gap: '5px', flexWrap: 'wrap' }}>
                          {statusAtual !== 'Pago' && statusAtual !== 'Cancelado' && (
                            <button onClick={() => alterarStatusFatura(fat.id, 'Pago')} style={styles.btnSmallGreen} title="Marcar como Pago">💲 Pago</button>
                          )}
                          <button onClick={() => prepararEmailOficial(fat)} style={{ backgroundColor: '#0056b3', color: 'white', border: 'none', padding: '6px 10px', borderRadius: '4px', cursor: 'pointer', fontSize: '12px', fontWeight: 'bold' }} title="Preparar E-mail">📧 E-mail</button>
                          <button onClick={() => gerarArquivoPDF(fat)} style={styles.btnSmallGray} title="Baixar Cópia PDF">📄 PDF</button>
                          {statusAtual !== 'Cancelado' && (
                            <>
                              <button onClick={() => carregarParaEdicao(fat)} style={styles.btnSmallBlue} title="Editar Fatura">✏️ Editar</button>
                              <button onClick={() => alterarStatusFatura(fat.id, 'Cancelado')} style={styles.btnSmallRed} title="Cancelar Fatura">❌ Canc</button>
                            </>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

const styles = {
  fieldset: { border: '1px solid #ccc', borderRadius: '8px', padding: '20px', marginBottom: '20px', backgroundColor: '#fff' },
  legend: { fontWeight: 'bold', color: '#555', padding: '0 10px' },
  row: { display: 'flex', gap: '15px', marginBottom: '15px', flexWrap: 'wrap' },
  inputGroup: { display: 'flex', flexDirection: 'column', flex: 1, minWidth: '150px' },
  label: { fontSize: '12px', color: '#666', marginBottom: '5px', fontWeight: 'bold' },
  input: { padding: '10px', border: '1px solid #ccc', borderRadius: '4px', fontSize: '14px', width: '100%', boxSizing: 'border-box' },
  btnBlue: { backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', padding: '0 20px', cursor: 'pointer', fontWeight: 'bold' },
  btnGreenOutline: { width: '100%', backgroundColor: '#28a745', color: 'white', border: 'none', borderRadius: '4px', padding: '10px', cursor: 'pointer', fontWeight: 'bold', marginTop: '10px' },
  btnGreenSolid: { width: '100%', backgroundColor: '#28a745', color: 'white', border: 'none', borderRadius: '8px', padding: '15px', cursor: 'pointer', fontSize: '16px', fontWeight: 'bold', marginTop: '10px' },
  btnMenuAtivo: { backgroundColor: '#333', color: 'white', border: 'none', padding: '12px 24px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '15px' },
  btnMenuInativo: { backgroundColor: '#e9ecef', color: '#555', border: '1px solid #ccc', padding: '12px 24px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '15px' },
  th: { padding: '12px', textAlign: 'left', color: '#555', fontSize: '14px' },
  td: { padding: '12px', fontSize: '14px', color: '#333', verticalAlign: 'middle' },
  btnSmallGreen: { backgroundColor: '#28a745', color: 'white', border: 'none', padding: '6px 10px', borderRadius: '4px', cursor: 'pointer', fontSize: '12px', fontWeight: 'bold' },
  btnSmallBlue: { backgroundColor: '#007bff', color: 'white', border: 'none', padding: '6px 10px', borderRadius: '4px', cursor: 'pointer', fontSize: '12px', fontWeight: 'bold' },
  btnSmallRed: { backgroundColor: '#dc3545', color: 'white', border: 'none', padding: '6px 10px', borderRadius: '4px', cursor: 'pointer', fontSize: '12px', fontWeight: 'bold' },
  btnSmallGray: { backgroundColor: '#6c757d', color: 'white', border: 'none', padding: '6px 10px', borderRadius: '4px', cursor: 'pointer', fontSize: '12px', fontWeight: 'bold' }
};